// TH18 v1.00a st04bs.ecl.txt:698-821 (BossCard2 / BossCard2_at), ranks 0-3.
// Source card "女王珠「虹の扉の向こうに」" (E/N "玉将「クイーンオブインヤンスフィア」"),
// spell id 36, setInterrupt(0,0,2700) + spell(36,2700).
// Shell: control enemy (0,0) owns the spell and the 120-frame prep buffer; the real
// boss starts at the common Boss entry (0,128) and keeps source hitboxes/judgment.
// Source t0 = first frame of b4_boss; TIME_LIMIT = 120 + 2700 + 2 = 2822.
const TIME_LIMIT: int = 2822;
const SOURCE_LIMIT: int = 2700;
const SPELL_ID: int = 36;

// TH18 bullet word table (godot/ecl/game/touhou-bullets.ecl).
const TH18_YIN_YANG_R: int = 1056;     // source etSprite type 44
const TH18_YIN_YANG_L: int = 1072;     // source etSprite type 45
const TH18_BIG_YIN_YANG_R: int = 1088; // source etSprite type 46
const HALF_FAN: int = 20480;           // 225deg fan / 2

// B:788-803 SHOOT_DATA cycles (45,2),(44,4),(45,6),(44,1) every 20 ticks.
// B:815-818 child EX from index15: ANIM(1), INVULN(120), WAIT(120), VELTIME(60,r=1).
// INVULN only writes the bomb-cancel counter (ex-effects.md); the EX cursor is not
// blocked by it, and training never bombs. Birth ANIM a=1 retreat is 4*0.1=0.4px.
xformdef CHILD_MOTION {
    @120 add_speed(0fx);       // explicit source WAIT(120)
    @60 set_accel(0.015fx);    // VELTIME (1.0-0.1)/60 per tick, heading kept
    set_accel(0fx);
}

// B:767-819. Every parent orb copies the whole 24-record EX program; slots 3/6/9/12
// are SHOOT, slots 4/7/10/13 the paired SHOOT_DATA, slot 14 GOTO back to slot 1.
// Slots 1-2 (INVULN one-shot, WAIT20) and the four WAIT20 between bursts make one
// continuous 20-tick cadence. sh_task starts one frame after birth, so wait(19)
// puts the first child burst on source t=20.
async sub big_orb_children() {
    var k: int = 0;
    wait(19);
    loop {
        var shape: int = TH18_YIN_YANG_L;
        var color: int = 2;
        if k == 1 { shape = TH18_YIN_YANG_R; color = 4; }
        if k == 2 { shape = TH18_YIN_YANG_L; color = 6; }
        if k == 3 { shape = TH18_YIN_YANG_R; color = 1; }
        // SHOOT a=1 fixed fan, c=2 ways, s=225deg, r=current parent angle.
        var aa: angle = $self_angle+(HALF_FAN as angle);
        var ab: angle = $self_angle-(HALF_FAN as angle);
        _ = fire(shape, color, $self_x-0.4fx*cos(aa), $self_y-0.4fx*sin(aa),
                 0.1fx, aa, CHILD_MOTION, none);
        _ = fire(shape, color, $self_x-0.4fx*cos(ab), $self_y-0.4fx*sin(ab),
                 0.1fx, ab, CHILD_MOTION, none);
        k = k+1;
        if k == 4 { k = 0; }
        wait(20);
    }
}

// B:767-819, called synchronously once per main-loop iteration; the source wait(180)
// is inside this helper. etNew(0) resets the whole emitter each call.
sub b4_at() {
    var rank: int = global(GVAR_RANK);
    var n: int = 6;
    if rank == 1 { n = 14; }
    if rank == 2 { n = 20; }
    if rank == 3 { n = 27; }

    // B:769-784: playSound dropped; etSprite type46 color0, mode3 fixed ring,
    // etAngle(%RANDRAD, pi/6) with M=1 -> base only, etSpeed(2.5,1.0) -> 2.5.
    var base: angle = (rand(65536)-32768) as angle;
    sh_reset(0);
    sh_sprite(0, TH18_BIG_YIN_YANG_R, 0);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, n, 1);
    sh_angle(0, base, 0deg);
    sh_speed(0, 2.5fx, 0fx);
    sh_dist(0, -10fx); // ANIM a1 retreat 4*2.5
    sh_task(0, big_orb_children);
    sh_fire(0);

    wait(180); // B:815
}

// B:698-765. Source t90 starts the synchronous at() loop:
// at(180) + wait190/194 + moveRand(60) + wait60 = 430/434 frames per wave.
async sub b4_boss() {
    set_invuln(65535);   // practice shell
    set_hitbox(24fx);    // B:27 setHitbox(48,48) -> radius 24
    set_hurtbox(20fx);   // B:26 setHurtbox(40,40) -> radius 20
    var until: int = $frame+SOURCE_LIMIT;

    // B:734-735: 60-frame quad-out move to (0,128); independent entry is already
    // (0,128), so this is the source zero-displacement timing. B:739 +90 label.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(90);
    loop {
        if $frame >= until { break; }
        b4_at();
        if $frame >= until { break; }
        var iv: int = 190; // B:745-753
        if global(GVAR_RANK) == 3 { iv = 194; }
        wait(iv);
        if $frame >= until { break; }
        card_move_rand();      // B:755 moveRand(60,4,1.0)
        card_wait(60, until);  // B:756
    }
    loop { wait(1); } // real enemy stays for the bullet tail until the spell ends
}

// B:726-764: the segment's spell timer is the 2700 source timeout.
async sub b4_pattern() {
    wait(120); // practice buffer; source t0 begins on the next boss task frame
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, b4_boss);
    loop { wait(1); }
}

// Extra control enemy at (0,0), no body collision; real boss keeps source judgment.
async sub b4_control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, SPELL_ID, b4_pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, b4_control);
    loop { wait(600); }
}

// TH18 v1.00a BossCard2 moveRand(60,4,1.0) with moveLimit(0,128,96,32) from B:735.
// Native limit: x in [-48,48], y in [96,160]; direction inner box x +-24, y 112..144.
// int slot0 = next step count, fx slot0/1 = logical unit direction.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.0fx*((60-k) as fx)/60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -48fx { nx = -48fx; }
    if nx > 48fx { nx = 48fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 405b90 = signed unit random * pi. Values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -24fx {
        a = r/3;
    } else if $self_x > 24fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon0.05rad. Nearest BAM boundaries (normal angle quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int, until: int) {
    for i in 0..frames {
        if $frame >= until { return; }
        wait(1);
        card_arm_next_step();
    }
}
